
const WORDS=[{"id": 0, "w": "婴儿", "p": "yīng'ér", "t": "名词", "m": "trẻ sơ sinh", "coll": "照顾婴儿、一个婴儿", "s": "照片里的婴儿如今已经长大，但母亲仍记得他小时候的模样。"}, {"id": 1, "w": "翻天覆地", "p": "fāntiān fùdì", "t": "成语", "m": "long trời lở đất, (thay đổi) to lớn/hoàn toàn", "coll": "翻天覆地的变化、发生翻天覆地的变化", "s": "短短十年间，这座城市发生了翻天覆地的变化。"}, {"id": 2, "w": "更新", "p": "gēngxīn", "t": "动词", "m": "đổi mới, thay mới", "coll": "更新信息、不断更新", "s": "随着新证据的出现，我们也应该及时更新原来的认识。"}, {"id": 3, "w": "酒窝", "p": "jiǔwō", "t": "名词", "m": "lúm đồng tiền", "coll": "脸上的酒窝、露出酒窝", "s": "她一笑，脸上就露出两个浅浅的酒窝，显得格外亲切。"}, {"id": 4, "w": "蹦", "p": "bèng", "t": "动词", "m": "nhảy", "coll": "蹦起来、又蹦又跳", "s": "听说可以去旅行，孩子高兴得一下子蹦了起来。"}, {"id": 5, "w": "跌", "p": "diē", "t": "动词", "m": "té, ngã", "coll": "跌了一跤、跌倒", "s": "下楼梯时，他不小心跌了一跤，幸好没有受伤。"}, {"id": 6, "w": "疤", "p": "bā", "t": "名词", "m": "vết sẹo", "coll": "一道疤、留下疤", "s": "他手臂上那道浅浅的疤，让他想起童年时的一次意外。"}, {"id": 7, "w": "掩盖", "p": "yǎngài", "t": "动词", "m": "che, phủ, che giấu", "coll": "掩盖事实、掩盖错误", "s": "承认错误比试图掩盖错误更需要勇气，也更有助于解决问题。"}, {"id": 8, "w": "大脑", "p": "dànǎo", "t": "名词", "m": "bộ óc, bộ não", "coll": "人类大脑、大脑活动", "s": "这本书用通俗的语言介绍了人类大脑的基本功能。"}, {"id": 9, "w": "确信", "p": "quèxìn", "t": "动词", "m": "tin chắc", "coll": "确信无疑、确信自己的判断", "s": "经过反复核对，她确信自己的计算没有问题。"}, {"id": 10, "w": "比喻", "p": "bǐyù", "t": "动词", "m": "ví như", "coll": "打比喻、比喻成一条河", "s": "老师把人生比喻成一条河，说明每个阶段都有不同的风景。"}, {"id": 11, "w": "呈现", "p": "chéngxiàn", "t": "动词", "m": "thể hiện, lộ ra", "coll": "呈现变化、呈现出特点", "s": "这份调查报告呈现了不同年龄学习者在学习习惯上的差异。"}, {"id": 12, "w": "固有", "p": "gùyǒu", "t": "形容词", "m": "vốn có, sẵn có", "coll": "固有观念、固有模式", "s": "面对新的问题，我们不应总是受固有观念的限制。"}, {"id": 13, "w": "阐述", "p": "chǎnshù", "t": "动词", "m": "trình bày, nêu rõ", "coll": "阐述观点、详细阐述", "s": "他结合实际案例，详细阐述了自己的研究观点。"}, {"id": 14, "w": "陈述", "p": "chénshù", "t": "动词", "m": "phát biểu, tuyên bố, nói rõ", "coll": "陈述事实、陈述理由", "s": "讨论问题时，请先客观地陈述事实，再表达个人意见。"}, {"id": 15, "w": "见解", "p": "jiànjiě", "t": "名词", "m": "cách nhìn, quan điểm", "coll": "提出见解、独到的见解", "s": "她对这个问题提出了独到的见解，引起了大家的兴趣。"}, {"id": 16, "w": "演变", "p": "yǎnbiàn", "t": "动词", "m": "diễn biến, biến đổi, tiến hóa", "coll": "逐渐演变、演变过程", "s": "这个小村庄经过多年的发展，逐渐演变成一座繁荣的小城。"}, {"id": 17, "w": "推测", "p": "tuīcè", "t": "动词", "m": "suy đoán, dự đoán", "coll": "合理推测、根据线索推测", "s": "仅凭一张照片，还很难准确推测当时发生了什么。"}, {"id": 18, "w": "譬如", "p": "pìrú", "t": "动词", "m": "ví dụ, như", "coll": "譬如学习语言、譬如读书", "s": "培养兴趣可以从身边的小事开始，譬如每天读几页书。"}, {"id": 19, "w": "各抒己见", "p": "gèshū jǐjiàn", "t": "成语", "m": "mỗi người phát biểu ý kiến của mình", "coll": "各抒己见、让大家各抒己见", "s": "讨论会上，大家各抒己见，从不同角度分析了这个问题。"}, {"id": 20, "w": "通缉", "p": "tōngjī", "t": "动词", "m": "truy nã/truy bắt (tội phạm)", "coll": "通缉嫌疑人、发布通缉令", "s": "警方发布通缉令，依法通缉在逃嫌疑人。"}, {"id": 21, "w": "触犯", "p": "chùfàn", "t": "动词", "m": "vi phạm, xâm phạm", "coll": "触犯法律、触犯规定", "s": "任何人都不能以不知情为借口触犯法律。"}, {"id": 22, "w": "惩罚", "p": "chéngfá", "t": "动词", "m": "trừng phạt nghiêm khắc", "coll": "受到惩罚、惩罚行为", "s": "违反规则的人应当受到相应的惩罚，同时也应该有改正错误的机会。"}, {"id": 23, "w": "忧郁", "p": "yōuyù", "t": "形容词", "m": "sầu muộn, buồn thương", "coll": "感到忧郁、忧郁的神情", "s": "离开家乡以后，他一度感到忧郁，后来逐渐适应了新的生活。"}, {"id": 24, "w": "肺", "p": "fèi", "t": "名词", "m": "phổi", "coll": "肺的功能、人的肺", "s": "老师借助图片介绍了人的肺在呼吸中的作用。"}, {"id": 25, "w": "器官", "p": "qìguān", "t": "名词", "m": "(sinh vật học) bộ phận, cơ quan", "coll": "身体器官、器官功能", "s": "这本教材用图示说明了人体主要器官的位置。"}, {"id": 26, "w": "移植", "p": "yízhí", "t": "动词", "m": "cấy, ghép", "coll": "移植树木、移植技术", "s": "为了保护这棵老树，工作人员制定了详细的移植方案。"}, {"id": 27, "w": "面貌", "p": "miànmào", "t": "名词", "m": "bộ mặt, diện mạo, tướng mạo", "coll": "精神面貌、城市面貌", "s": "经过大家的共同努力，社区呈现出崭新的面貌。"}, {"id": 28, "w": "极端", "p": "jíduān", "t": "形容词", "m": "cực đoan, quá khích", "coll": "走向极端、极端的做法", "s": "处理分歧时，不要走向极端，而应耐心寻找共同点。"}, {"id": 29, "w": "空前绝后", "p": "kōngqián juéhòu", "t": "成语", "m": "có một không hai", "coll": "空前绝后的成就、空前绝后的盛况", "s": "评论者把这次演出的盛况形容为空前绝后。"}, {"id": 30, "w": "昏迷", "p": "hūnmí", "t": "动词", "m": "hôn mê, bất tỉnh", "coll": "陷入昏迷、从昏迷中醒来", "s": "小说中的主人公在事故后陷入昏迷，醒来时发现周围的一切都变了。"}, {"id": 31, "w": "清醒", "p": "qīngxǐng", "t": "形容词／动词", "m": "tỉnh lại", "coll": "保持清醒、头脑清醒", "s": "面对夸奖，他仍然保持清醒，知道自己还有很多不足。"}, {"id": 32, "w": "言论", "p": "yánlùn", "t": "名词", "m": "ngôn luận, lời bàn", "coll": "发表言论、不负责任的言论", "s": "在网上发表言论时，也应该尊重事实，对自己的话负责。"}, {"id": 33, "w": "学说", "p": "xuéshuō", "t": "名词", "m": "học thuyết", "coll": "提出学说、研究学说", "s": "这位学者提出了一种新的学说，试图解释语言与思维之间的关系。"}, {"id": 34, "w": "遥远", "p": "yáoyuǎn", "t": "形容词", "m": "xa xôi, xa vời", "coll": "遥远的地方、遥远的回忆", "s": "那段童年的往事虽然已经十分遥远，却仍然深深留在他的记忆里。"}, {"id": 35, "w": "陷入", "p": "xiànrù", "t": "动词", "m": "rơi vào, sa vào", "coll": "陷入困境、陷入沉思", "s": "听完老师的话，她陷入沉思，重新考虑自己的选择。"}, {"id": 36, "w": "思索", "p": "sīsuǒ", "t": "动词", "m": "suy nghĩ tìm tòi", "coll": "认真思索、反复思索", "s": "这个问题值得我们认真思索，而不是急于下结论。"}, {"id": 37, "w": "设想", "p": "shèxiǎng", "t": "动词", "m": "tưởng tượng", "coll": "设想未来、大胆设想", "s": "我们可以大胆设想未来的生活，但也需要一步一步地付诸行动。"}, {"id": 38, "w": "性命", "p": "xìngmìng", "t": "名词", "m": "tính mạng, mạng sống", "coll": "挽救性命、危及性命", "s": "救援人员及时赶到，挽救了被困者的性命。"}, {"id": 39, "w": "无忧无虑", "p": "wúyōu wúlǜ", "t": "成语", "m": "vô tư lự, không lo lắng gì hết", "coll": "无忧无虑的童年、无忧无虑地生活", "s": "每次翻看旧照片，她都会想起那段无忧无虑的童年时光。"}, {"id": 40, "w": "崭新", "p": "zhǎnxīn", "t": "形容词", "m": "hoàn toàn mới, mới tinh", "coll": "崭新的生活、崭新的起点", "s": "离开熟悉的城市后，她开始了一段崭新的生活。"}];
